/// @file mouth_script.hpp
/// @brief Jaw keyframes synced to the voice clips.
///
/// GENERATED by tools/make_jaw_script.py -- do not edit by hand. Re-run the
/// script whenever the voice clips change.

#pragma once

#include <avr/pgmspace.h>
